       {"label": "Contribution Margin", "expression": "(1000000 - 600000)"},
       {"label": "Profit Before Interest and Tax", "expression": "(1000000 - 600000 - 300000)"},
       {"label": "Operational Gearing", "expression": "((1000000 - 600000) / (1000000 - 600000 - 300000))"}
   ],
